SELECT 
FROM yms_yard_position p
LEFT JOIN yms_yard_zone z ON p.zone_id = z.id AND z.deleted = 0
WHERE p.deleted = 0

      AND p.warehouse_id = #{bo.warehouseId}


      AND p.zone_id = #{bo.zoneId}


      AND p.position_code LIKE CONCAT('%', #{bo.positionCode}, '%')


      AND p.position_type = #{bo.positionType}


      AND p.position_status = #{bo.positionStatus}


      AND p.occupied_object_no LIKE CONCAT('%', #{bo.occupiedObjectNo}, '%')

ORDER BY z.sort_order ASC, p.grid_row ASC, p.grid_col ASC, p.position_code ASC

SELECT FROM yms_yard_position p LEFT JOIN yms_yard_zone z ON p.zone_id = z.id AND z.deleted = 0 WHERE p.deleted = 0 AND p.warehouse_id = #{warehouseId} AND p.position_status = 'FREE'
AND p.position_type = #{positionType}
ORDER BY z.sort_order ASC, p.position_code ASC
